<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Northwind consolidation review</title>
  <link rel="stylesheet" href="style.css">
</head>
<body>
  <header>
    <a href="#/" class="brand">Northwind consolidation review</a>
    <span class="local">local only · 127.0.0.1 · no live model call</span>
  </header>
  <nav id="stepper" aria-label="Steps"></nav>
  <main id="view" aria-live="polite"></main>
  <script src="app.js"></script>
  <script src="steps.js"></script>
  <script>route();</script>
</body>
</html>
:root { --ink: #1c2330; --muted: #5b6577; --line: #d9dee7; --bg: #f6f7f9; --card: #fff;
        --accent: #1f5fbf; --ok: #1d7a46; --warn: #a15c00; --bad: #b3261e; }
* { box-sizing: border-box; }
body { margin: 0; font: 15px/1.45 system-ui, sans-serif; color: var(--ink); background: var(--bg); }
header { display: flex; justify-content: space-between; align-items: baseline; padding: 12px 24px; background: var(--ink); }
.brand { color: #fff; font-weight: 600; text-decoration: none; }
.local { color: #aab4c5; font-size: 13px; }
#stepper { display: flex; flex-wrap: wrap; gap: 4px; padding: 10px 24px 0; }
#stepper a { padding: 6px 12px; border: 1px solid var(--line); border-radius: 6px 6px 0 0; background: #eceff4;
             color: var(--muted); text-decoration: none; }
#stepper a.here { background: var(--card); color: var(--ink); font-weight: 600; border-bottom-color: var(--card); }
#stepper a.locked { pointer-events: none; opacity: .5; }
main { margin: 0 24px 40px; padding: 20px; background: var(--card); border: 1px solid var(--line); max-width: 1100px; }
h1 { font-size: 20px; margin: 0 0 12px; } h2 { font-size: 16px; margin: 24px 0 8px; }
table { border-collapse: collapse; width: 100%; margin: 6px 0; }
th, td { text-align: left; padding: 6px 8px; border-bottom: 1px solid var(--line); vertical-align: top; }
th { color: var(--muted); font-weight: 600; font-size: 13px; }
button, .btn { font: inherit; padding: 6px 14px; border: 1px solid var(--accent); background: var(--accent); color: #fff;
               border-radius: 6px; cursor: pointer; text-decoration: none; display: inline-block; }
button.plain { background: #fff; color: var(--accent); }
button:disabled { opacity: .45; cursor: not-allowed; }
input, select { font: inherit; padding: 5px 8px; border: 1px solid var(--line); border-radius: 6px; }
.row { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin: 8px 0; }
.tag { padding: 1px 8px; border-radius: 10px; font-size: 12px; border: 1px solid var(--line); }
.determined, .ok { color: var(--ok); } .provisional, .warn { color: var(--warn); }
.unknown, .bad { color: var(--bad); } .muted { color: var(--muted); }
.note { padding: 8px 12px; border-left: 3px solid var(--accent); background: #eef3fb; margin: 10px 0; }
.error { padding: 8px 12px; border-left: 3px solid var(--bad); background: #fbeeee; margin: 10px 0; }
code { background: #eef0f4; padding: 1px 5px; border-radius: 4px; }
// Review UI: hash router, API helper and the runs list. Everything from the server is put on the page with
// text nodes (never as HTML), so uploaded text is shown as data and cannot run as script.
const STEPS = [["upload", "1 Upload"], ["review", "2 Review"], ["outputs", "3 Choose outputs"],
               ["build", "4 Build"], ["results", "5 Results"], ["export", "6 Export"]];
const view = document.getElementById("view");
const stepper = document.getElementById("stepper");

function h(tag, attrs = {}, ...kids) {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k.startsWith("on")) el.addEventListener(k.slice(2), v);
    else if (v === true) el.setAttribute(k, "");
    else if (v !== false && v != null) el.setAttribute(k, v);
  }
  for (const kid of kids.flat()) if (kid != null) el.append(kid.nodeType ? kid : String(kid));
  return el;
}

async function api(method, path, body, raw) {
  const init = { method, headers: {} };
  if (raw !== undefined) init.body = raw;
  else if (body !== undefined) { init.body = JSON.stringify(body); init.headers["Content-Type"] = "application/json"; }
  const res = await fetch("/api" + path, init);
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(typeof data.detail === "string" ? data.detail : JSON.stringify(data.detail || res.status));
  return data;
}

function show(...nodes) { view.replaceChildren(...nodes); }
function fail(error) { view.prepend(h("div", { class: "error" }, String(error.message || error))); }
function table(head, rows) {
  return h("table", {}, h("thead", {}, h("tr", {}, head.map((t) => h("th", {}, t)))),
           h("tbody", {}, rows.map((r) => h("tr", {}, r.map((c) => h("td", {}, c))))));
}
function when(text) { return new Date(text).toLocaleString(); }
function shown(v) { return v === null ? "null" : typeof v === "object" ? JSON.stringify(v) : String(v); }

function drawStepper(run, step) {
  stepper.replaceChildren(...(run ? STEPS.map(([key, label]) =>
    h("a", { href: `#/run/${run.id}/${key}`, class: key === step ? "here" : "" }, label)) : []));
}

function nextStep(run) {
  return { new: "upload", awaiting_review: "review", done: "results" }[run.status] || "review";
}

async function runsList() {
  drawStepper(null);
  const runs = await api("GET", "/runs");
  const name = h("input", { placeholder: "run name", maxlength: 60 });
  const sample = h("input", { type: "checkbox" });
  const create = async () => {
    try {
      const run = await api("POST", "/runs", { name: name.value, use_sample: sample.checked });
      location.hash = `#/run/${run.id}/upload`;
    } catch (e) { fail(e); }
  };
  show(h("h1", {}, "Runs"),
    h("div", { class: "row" }, name, h("label", {}, sample, " start with the supplied sample files"),
      h("button", { onclick: create }, "New run")),
    runs.length ? table(["Name", "Id", "Status", "Created", "Based on", ""], runs.map((r) => [
      r.name, h("code", {}, r.id), h("span", { class: "tag" }, r.status), when(r.created), r.parent || "",
      h("a", { class: "btn plain", href: `#/run/${r.id}/${nextStep(r)}` },
        r.status === "awaiting_review" ? "Resume" : "Open")])) : h("p", { class: "muted" }, "No runs yet."));
}

async function route() {
  const [, kind, id, step] = location.hash.split("/");
  try {
    if (kind !== "run") return await runsList();
    const run = await api("GET", `/runs/${id}`);
    const chosen = STEPS.some(([k]) => k === step) ? step : nextStep(run);
    drawStepper(run, chosen);
    await STEP_VIEWS[chosen](run);
  } catch (e) { show(h("div", { class: "error" }, String(e.message || e)), h("a", { href: "#/" }, "Back to runs")); }
}
window.addEventListener("hashchange", route);
// The six step views. Each reads from the API and draws; no number is calculated here.
const head = (run, title) => [h("h1", {}, title), h("p", { class: "muted" }, run.name + " · ", h("code", {}, run.id))];
const go = (run, step) => { location.hash = `#/run/${run.id}/${step}`; };
// Display only: the engine's gate detail carries Decimal reprs and 40-digit differences; show them readably.
const tidy = (t) => t.replace(/Decimal\('([^']+)'\)/g, "$1").replace(/(\d+\.\d{6})\d+/g, "$1").replace(/-?\d+(\.\d+)?E-\d{2,}/g, "0");
const button = (label, onclick, plain) => h("button", { onclick, class: plain ? "plain" : "" }, label);

async function uploadStep(run) {
  const rows = (files) => table(["File", "State", "Contract"], files.map((f) => [h("code", {}, f.name),
    f.present && !f.error ? h("span", { class: "ok" }, `ok (${f.bytes} bytes)`) :
      h("span", { class: "bad" }, f.present ? "rejected" : "missing"), f.error || ""]));
  const input = h("input", { type: "file", multiple: true });
  const upload = async () => {
    const results = [];
    for (const file of input.files) {
      try {
        const r = await api("PUT", `/runs/${run.id}/files/${encodeURIComponent(file.name)}`, undefined, await file.arrayBuffer());
        if (!r.stored) results.push(`${file.name}: ${r.error}`);
      } catch (e) { results.push(`${file.name}: ${e.message}`); }
    }
    await uploadStep(run);
    results.forEach((t) => view.prepend(h("div", { class: "error" }, t)));
  };
  const fresh = await api("GET", `/runs/${run.id}`);
  const ready = fresh.files.every((f) => f.present && !f.error);
  const next = async () => { try { await api("POST", `/runs/${run.id}/analyse`); go(run, "review"); } catch (e) { fail(e); } };
  show(...head(run, "1 Upload"), h("div", { class: "note" }, "Only the 15 expected file names are accepted, up to 1 MB each. " +
    "A file that breaks its contract is refused and the reason is shown on its row."),
    h("div", { class: "row" }, input, button("Upload", upload)), rows(fresh.files),
    h("div", { class: "row" }, h("button", { onclick: next, disabled: !ready }, "Analyse and go to Review")));
}

async function reviewStep(run) {
  if (run.status === "new") {
    return show(...head(run, "2 Review"), h("p", {}, "This run has not been analysed yet."),
      button("Analyse", async () => { try { await api("POST", `/runs/${run.id}/analyse`); await route(); } catch (e) { fail(e); } }));
  }
  const rv = await api("GET", `/runs/${run.id}/review`);
  const marks = {};
  const approver = h("input", { placeholder: "your name", maxlength: 60 });
  const waiting = rv.queue.filter((q) => rv.open_items.includes(q.key));
  const choose = (q) => h("select", { onchange: (e) => { marks[q.key] = e.target.value; } },
    ["", "approve", "reject"].map((v) => h("option", { value: v }, v || "undecided")));
  const send = async () => {
    const decisions = Object.fromEntries(Object.entries(marks).filter(([, v]) => v));
    try { await api("POST", `/runs/${run.id}/decisions`, { approver: approver.value, decisions }); await route(); }
    catch (e) { fail(e); }
  };
  const advice = rv.advice.map((a) => [a.kind, a.unit, a.recorded ? "recorded model answer" : "not recorded (rule fallback)",
    a.verified.join(", "), a.unverified.join(", "), a.dropped.map((d) => `${d.claim}: ${d.why}`).join("; "), a.missed.join(", ")]);
  show(...head(run, "2 Review"), h("p", {}, "Status: ", h("span", { class: "tag" }, run.status)),
    waiting.length ? h("div", {}, h("h2", {}, "Waiting for a decision"),
      table(["Item", "State", "Reason", "Decision"], waiting.map((q) => [h("code", {}, q.key), q.state, q.reason, choose(q)])),
      h("div", { class: "row" }, approver, button("Submit decisions", send))) :
      h("div", { class: "note" }, "Nothing is waiting for a decision."),
    h("h2", {}, `Findings (${rv.findings.length})`),
