"""Run registry, upload, review and build endpoints. Each calls one existing service."""
from typing import Annotated, Any

from fastapi import APIRouter, Depends, HTTPException, Request

from app.api_models import Decisions, NewRun
from app.services import pipeline_service as pipeline
from app.services.registry_service import Registry
from app.services.upload_service import EXPECTED_FILES, MAX_BYTES, file_status, validate_bytes

router = APIRouter(prefix="/api")


def registry(request: Request) -> Registry:
    reg: Registry = request.app.state.registry
    return reg


Reg = Annotated[Registry, Depends(registry)]


@router.get("/runs")
def list_runs(reg: Reg) -> list[dict[str, Any]]:
    return reg.list()


@router.post("/runs")
def create_run(body: NewRun, reg: Reg) -> dict[str, Any]:
    return reg.create(body.name, body.use_sample)


@router.get("/runs/{run_id}")
def open_run(run_id: str, reg: Reg) -> dict[str, Any]:
    return reg.meta(run_id) | {"files": file_status(reg.data_dir(run_id))}


@router.put("/runs/{run_id}/files/{name}")
async def upload(run_id: str, name: str, request: Request, reg: Reg) -> dict[str, Any]:
    """The body is the raw file. It is checked against its contract in a scratch copy, then stored only if it passes."""
    if name not in EXPECTED_FILES:
        raise HTTPException(422, f"{name} is not one of the 15 expected files")
    folder = reg.data_dir(run_id)
    body = await request.body()
    if len(body) > MAX_BYTES:
        raise HTTPException(413, f"{name} is larger than {MAX_BYTES} bytes")
    error = validate_bytes(name, body)
    if error is None:
        (folder / name).write_bytes(body)
    return {"name": name, "stored": error is None, "error": error}


@router.post("/runs/{run_id}/analyse")
def analyse(run_id: str, reg: Reg) -> dict[str, Any]:
    return pipeline.analyse(reg, run_id)


@router.get("/runs/{run_id}/review")
def review(run_id: str, reg: Reg) -> dict[str, Any]:
    return pipeline.review_view(reg, run_id)


@router.post("/runs/{run_id}/decisions")
def decide(run_id: str, body: Decisions, reg: Reg) -> dict[str, Any]:
    return pipeline.decide(reg, run_id, body.approver, body.decisions)


@router.post("/runs/{run_id}/build")
def build(run_id: str, reg: Reg) -> dict[str, Any]:
    return pipeline.build(reg, run_id)
"""Results, what-if, compare, output choice and export endpoints."""
from typing import Any

from fastapi import APIRouter, HTTPException, Response

from app.api_models import Outputs, WhatIf
from app.routes import Reg
from app.services import pipeline_service as pipeline
from app.services import results_service as results
from app.services.pipeline_service import NotReady
from app.services.whatif_service import Change, patched_copy

router = APIRouter(prefix="/api")


def _finished(reg: Reg, run_id: str) -> None:
    if reg.meta(run_id)["status"] != "done":
        raise NotReady("the run has not finished")


@router.get("/runs/{run_id}/results")
def get_results(run_id: str, reg: Reg) -> dict[str, Any]:
    _finished(reg, run_id)
    out = reg.out_dir(run_id)
    return {"figures": results.figures(out), "issues": results.issues(out)}


@router.get("/runs/{run_id}/outputs")
def get_outputs(run_id: str, reg: Reg) -> dict[str, Any]:
    _finished(reg, run_id)
    return {"available": results.available_outputs(reg.out_dir(run_id)), "chosen": reg.meta(run_id)["outputs"]}


@router.put("/runs/{run_id}/outputs")
def choose_outputs(run_id: str, body: Outputs, reg: Reg) -> dict[str, Any]:
    _finished(reg, run_id)
    results.build_zip(reg.out_dir(run_id), body.files)
    return reg.update(run_id, outputs=body.files)


@router.post("/runs/{run_id}/whatif")
def whatif(run_id: str, body: WhatIf, reg: Reg) -> dict[str, Any]:
    """A changed input becomes a new run beside the old one; the old run is never touched."""
    parent = reg.meta(run_id)
    new = reg.create(body.name or f"what-if on {parent['name']}", parent=run_id,
                     copy_config_from=reg.config_dir(run_id))
    try:
        patched_copy(reg.data_dir(run_id), reg.data_dir(new["id"]), Change(body.patches, body.appends))
    except (ValueError, IndexError, KeyError, OSError) as error:
        raise HTTPException(422, f"change could not be applied: {error}") from error
    return pipeline.analyse(reg, new["id"])


@router.get("/runs/{run_id}/compare/{other_id}")
def compare(run_id: str, other_id: str, reg: Reg) -> dict[str, Any]:
    _finished(reg, run_id)
    _finished(reg, other_id)
    return results.compare(reg, run_id, other_id)


@router.get("/runs/{run_id}/export")
def export(run_id: str, reg: Reg) -> Response:
    _finished(reg, run_id)
    chosen = reg.meta(run_id)["outputs"] or [o["name"] for o in results.available_outputs(reg.out_dir(run_id))]
    return Response(results.build_zip(reg.out_dir(run_id), chosen), media_type="application/zip",
                    headers={"Content-Disposition": f'attachment; filename="{run_id}.zip"'})
"""Request and response shapes for the review UI. Plain data: no figure is computed here."""
import re

from pydantic import BaseModel, Field, field_validator

from app.services.upload_service import EXPECTED_FILES

PATCH = re.compile(r"^(?P<file>[^:]+):\d+\.\w+=")
APPEND = re.compile(r"^(?P<file>[^=]+)=")


class NewRun(BaseModel):
    name: str = Field(default="", max_length=60)
    use_sample: bool = False


class Decisions(BaseModel):
    approver: str = Field(min_length=1, max_length=60)
    decisions: dict[str, str]

    @field_validator("decisions")
    @classmethod
    def only_approve_or_reject(cls, value: dict[str, str]) -> dict[str, str]:
        bad = sorted(t for t, choice in value.items() if choice not in {"approve", "reject"})
        if bad:
            raise ValueError(f"decision must be approve or reject: {bad}")
        return value


class Outputs(BaseModel):
    files: list[str]


class WhatIf(BaseModel):
    """Patches look like file:LINE.column=value, appends like file=csv row. The file must be one of the 15."""

    name: str = Field(default="", max_length=60)
    patches: list[str] = Field(default_factory=list, max_length=20)
    appends: list[str] = Field(default_factory=list, max_length=20)

    @field_validator("patches", "appends")
    @classmethod
    def known_file(cls, value: list[str], info: object) -> list[str]:
        pattern = PATCH if getattr(info, "field_name", "") == "patches" else APPEND
        for text in value:
            match = pattern.match(text)
            if not match or match["file"] not in EXPECTED_FILES:
                raise ValueError(f"{text!r}: expected a change to one of the 15 supplied files")
        return value
