:root { color-scheme: light dark;
  --bg: #f3f5f9; --card: #ffffff; --ink: #172033; --muted: #4a5568; --line: #d3d9e4; --soft: #eef2f8;
  --accent: #1d4ed8; --on-accent: #ffffff; --ok: #0e6b39; --warn: #8a4b00; --bad: #a61b1b;
  --ok-bg: #e6f4ec; --warn-bg: #fdf1dc; --bad-bg: #fbe9e9; --info-bg: #e8effd; --focus: #b45309; }
@media (prefers-color-scheme: dark) { :root {
  --bg: #0e1420; --card: #161f2f; --ink: #e8edf6; --muted: #a8b3c7; --line: #2c3a52; --soft: #1d2a3f;
  --accent: #8ab4ff; --on-accent: #0b1220; --ok: #6fd69a; --warn: #f4b862; --bad: #ff9a92;
  --ok-bg: #12301f; --warn-bg: #36280f; --bad-bg: #3a1a1a; --info-bg: #17284a; --focus: #fbbf24; } }
* { box-sizing: border-box; }
body { margin: 0; font: 16px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; color: var(--ink);
       background: var(--bg); min-height: 100vh; display: flex; flex-direction: column; }
:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; border-radius: 4px; }
.skip { position: absolute; left: -999px; } .skip:focus { left: 8px; top: 8px; background: var(--card); padding: 6px 10px; z-index: 5; }
.top { display: flex; flex-wrap: wrap; gap: 8px 24px; align-items: center; padding: 12px 24px; background: var(--card);
       border-bottom: 1px solid var(--line); }
.brand { font-weight: 700; color: var(--ink); text-decoration: none; font-size: 18px; }
.runbar { display: flex; flex-wrap: wrap; gap: 4px 12px; align-items: center; color: var(--muted); }
.runbar strong { color: var(--ink); }
.layout { display: grid; grid-template-columns: 220px minmax(0, 1fr); gap: 24px; padding: 24px; flex: 1;
          width: 100%; max-width: 1280px; margin: 0 auto; align-items: start; }
.stepper { display: flex; flex-direction: column; gap: 4px; position: sticky; top: 16px; }
.stepper a, .stepper span.item { display: flex; gap: 10px; align-items: center; padding: 8px 10px; border-radius: 8px;
  color: var(--ink); text-decoration: none; border: 1px solid transparent; }
.stepper a:hover { background: var(--soft); }
.stepper .dot { flex: none; width: 26px; height: 26px; border-radius: 50%; display: grid; place-items: center; font-size: 13px;
  font-weight: 700; border: 2px solid var(--muted); color: var(--muted); }
.stepper .state { display: block; font-size: 12px; color: var(--muted); }
.stepper .done .dot { background: var(--ok); border-color: var(--ok); color: var(--card); }
.stepper .blocked .dot { background: var(--bad); border-color: var(--bad); color: var(--card); }
.stepper .current { background: var(--info-bg); border-color: var(--accent); font-weight: 600; }
.stepper .current .dot { border-color: var(--accent); color: var(--accent); }
.stepper .locked { opacity: .65; pointer-events: none; }
main { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 24px; min-width: 0; }
main:focus { outline: none; }
h1 { font-size: 24px; line-height: 1.25; margin: 0 0 4px; } h2 { font-size: 18px; margin: 28px 0 8px; }
h3 { font-size: 16px; margin: 0 0 6px; }
.lede { color: var(--muted); margin: 0 0 16px; }
.foot { padding: 16px 24px; color: var(--muted); font-size: 13px; text-align: center; border-top: 1px solid var(--line); }
table { border-collapse: collapse; width: 100%; margin: 8px 0; font-size: 15px; }
th, td { text-align: left; padding: 8px 10px; border-bottom: 1px solid var(--line); vertical-align: top; }
th { color: var(--muted); font-weight: 600; font-size: 13px; }
.scroll { overflow-x: auto; }
button, .btn { font: inherit; padding: 8px 16px; border: 1px solid var(--accent); background: var(--accent); color: var(--on-accent);
  border-radius: 8px; cursor: pointer; text-decoration: none; display: inline-block; min-height: 40px; }
button.plain, .btn.plain { background: transparent; color: var(--accent); }
button:disabled { opacity: .5; cursor: not-allowed; }
input, select { font: inherit; padding: 8px 10px; border: 1px solid var(--muted); border-radius: 8px; background: var(--card);
  color: var(--ink); min-height: 40px; max-width: 100%; }
.row { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin: 12px 0; }
.tag { padding: 2px 10px; border-radius: 999px; font-size: 13px; border: 1px solid var(--line); background: var(--soft); white-space: nowrap; }
.determined, .ok { color: var(--ok); } .provisional, .warn { color: var(--warn); }
.unknown, .bad { color: var(--bad); } .muted { color: var(--muted); }
.callout { padding: 10px 14px; border-left: 4px solid var(--accent); background: var(--info-bg); margin: 12px 0; border-radius: 6px; }
.callout.ok { border-color: var(--ok); background: var(--ok-bg); color: var(--ink); }
